import json
import os

from tests.support import CliCase


class StockTests(CliCase):
    def test_stock_text(self):
        self.assertEqual(
            self.ok("stock"),
            "AB-100 17 ok Garden gnome\nCD-205 40 low Seed packet, mix\nEF-310 0 out Gift voucher\n",
        )

    def test_stock_json(self):
        self.assertEqual(
            self.ok("stock", "--json"),
            json.dumps(
                [
                    {"sku": "AB-100", "name": "Garden gnome", "onhand": 17, "status": "ok"},
                    {"sku": "CD-205", "name": "Seed packet, mix", "onhand": 40, "status": "low"},
                    {"sku": "EF-310", "name": "Gift voucher", "onhand": 0, "status": "out"},
                ],
                indent=2,
            )
            + "\n",
        )

    def test_status_boundaries(self):
        self.write("catalog.txt", "AA-001|a|1|3\nAA-002|b|1|0\nAA-003|c|1|3\nAA-004|d|1|3\n")
        self.write("movements.txt", "2024-01-01 AA-001 4\n2024-01-01 AA-002 1\n2024-01-01 AA-003 3\n2024-01-01 AA-004 1\n")
        self.assertEqual(self.ok("stock"), "AA-001 4 ok a\nAA-002 1 ok b\nAA-003 3 low c\nAA-004 1 low d\n")

    def test_sorted_by_sku_not_file_order(self):
        self.write("catalog.txt", "ZZ-999|z|1|0\nAA-001|a|1|0\n")
        self.write("movements.txt", "")
        self.assertEqual(self.ok("stock"), "AA-001 0 out a\nZZ-999 0 out z\n")

    def test_unicode_name(self):
        self.write("catalog.txt", "AA-001|café ☃|1|0\n")
        self.assertEqual(self.ok("stock"), "AA-001 0 out café ☃\n")
        self.assertIn("café ☃", self.ok("stock", "--json"))

    def test_bom_and_crlf_everywhere(self):
        self.write("catalog.txt", b"\xef\xbb\xbf# c\r\nAB-100|g|1|5\r\n")
        self.write("movements.txt", b"\xef\xbb\xbf2024-01-01 AB-100 +7 hi\r\n")
        self.assertEqual(self.ok("stock"), "AB-100 7 ok g\n")
        self.assertEqual(self.ok("history", "AB-100"), "2024-01-01 +7 7 hi\n")

    def test_missing_movements_is_empty(self):
        os.remove(self.path("movements.txt"))
        self.assertEqual(self.ok("stock").splitlines()[0], "AB-100 0 out Garden gnome")


class LowTests(CliCase):
    def test_low_text(self):
        self.assertEqual(self.ok("low"), "CD-205 40 40 40\nEF-310 0 0 1\n")

    def test_low_json(self):
        self.assertEqual(
            json.loads(self.ok("low", "--json")),
            [
                {"sku": "CD-205", "onhand": 40, "reorder": 40, "buy": 40},
                {"sku": "EF-310", "onhand": 0, "reorder": 0, "buy": 1},
            ],
        )

    def test_buy_formula(self):
        self.write("catalog.txt", "AA-001|a|1|10\nAA-002|b|1|10\nAA-003|c|1|2\n")
        self.write("movements.txt", "2024-01-01 AA-001 3\n2024-01-01 AA-003 2\n")
        self.assertEqual(self.ok("low"), "AA-001 3 10 17\nAA-002 0 10 20\nAA-003 2 2 2\n")

    def test_nothing_low_prints_nothing(self):
        self.write("movements.txt", "2024-01-01 AB-100 50\n2024-01-01 CD-205 50\n2024-01-01 EF-310 1\n")
        r = self.run_cli("low")
        self.assertEqual((r.code, r.out, r.err), (0, "", ""))
        self.assertEqual(self.ok("low", "--json"), "[]\n")


class HistoryTests(CliCase):
    def test_history_text(self):
        self.assertEqual(self.ok("history", "ab-100"), "2024-03-01 +20 20 first delivery\n2024-03-04 -3 17 order SO-1001\n")

    def test_history_without_note_has_no_trailing_space(self):
        self.assertEqual(self.ok("history", "CD-205"), "2024-03-05 +40 40\n")

    def test_history_json(self):
        self.assertEqual(
            json.loads(self.ok("history", "AB-100", "--json")),
            [
                {"date": "2024-03-01", "delta": "+20", "balance": 20, "note": "first delivery"},
                {"date": "2024-03-04", "delta": "-3", "balance": 17, "note": "order SO-1001"},
            ],
        )
        self.assertEqual(self.ok("history", "--json", "EF-310"), "[]\n")

    def test_counting_order_not_file_order(self):
        self.write("movements.txt", "2024-03-05 AB-100 -2 b\n2024-03-01 AB-100 +5 a\n2024-03-05 AB-100 +1 c\n")
        self.assertEqual(self.ok("history", "AB-100"), "2024-03-01 +5 5 a\n2024-03-05 -2 3 b\n2024-03-05 +1 4 c\n")

    def test_unknown_or_malformed_sku_refused(self):
        self.assertIn("ZZ-999", self.fails(1, "history", "ZZ-999"))
        self.fails(1, "history", "nonsense")
        self.fails(1, "history", "")


class ReceiveShipTests(CliCase):
    def test_receive_appends_and_prints(self):
        out = self.ok("receive", "2024-04-01", "ab-100", "5", "  second delivery \t")
        self.assertEqual(out, "2024-04-01 AB-100 +5 second delivery\n")
        self.assertEqual(self.read("movements.txt"), (self.movements + out).encode())

    def test_ship_appends_without_note(self):
        out = self.ok("ship", "2024-04-01", "AB-100", "007")
        self.assertEqual(out, "2024-04-01 AB-100 -7\n")
        self.assertTrue(self.read("movements.txt").endswith(b"2024-04-01 AB-100 -7\n"))

    def test_missing_final_newline_is_added(self):
        self.write("movements.txt", "2024-03-01 AB-100 +20")
        self.ok("receive", "2024-03-02", "AB-100", "1")
        self.assertEqual(self.read("movements.txt"), b"2024-03-01 AB-100 +20\n2024-03-02 AB-100 +1\n")

    def test_crlf_file_gets_lf_line(self):
        self.write("movements.txt", "2024-03-01 AB-100 +20\r\n")
        self.ok("ship", "2024-03-02", "AB-100", "1")
        self.assertEqual(self.read("movements.txt"), b"2024-03-01 AB-100 +20\r\n2024-03-02 AB-100 -1\n")

    def test_creates_missing_file_and_empty_file(self):
        os.remove(self.path("movements.txt"))
        self.ok("receive", "2024-03-02", "AB-100", "4")
        self.assertEqual(self.read("movements.txt"), b"2024-03-02 AB-100 +4\n")
        self.write("movements.txt", "")
        self.ok("receive", "2024-03-02", "AB-100", "4")
        self.assertEqual(self.read("movements.txt"), b"2024-03-02 AB-100 +4\n")

    def test_dash_led_args_are_taken_as_typed(self):
        self.assertEqual(self.ok("receive", "2024-04-01", "AB-100", "5", "--json"), "2024-04-01 AB-100 +5 --json\n")
        self.fails(1, "receive", "2024-04-01", "AB-100", "-5")
        self.fails(1, "ship", "2024-04-01", "AB-100", "--json")
        self.assertEqual(self.ok("ship", "2024-04-01", "AB-100", "1", "-n"), "2024-04-01 AB-100 -1 -n\n")

    def test_refusals_leave_file_untouched(self):
        for args in (
            ("2024-04-01", "AB-100", "0"),
            ("2024-04-01", "AB-100", "+5"),
            ("2024-04-01", "AB-100", "1.5"),
            ("2024-04-01", "AB-100", "abc"),
            ("2024-04-01", "AB-100", ""),
            ("2024-04-01", "AB-100", "٥"),
            ("2024-04-01", "ZZ-999", "5"),
            ("2024-04-01", "bad", "5"),
            ("2024-04-01", "AB-100", "5", "line\nbreak"),
            ("2024-04-01", "AB-100", "5", "line\rbreak"),
        ):
            for cmd in ("receive", "ship"):
                with self.subTest(cmd=cmd, args=args):
                    self.fails(1, cmd, *args)

    def test_would_go_below_zero(self):
        self.assertIn("below zero", self.fails(1, "ship", "2024-04-01", "AB-100", "18"))
        self.ok("ship", "2024-04-01", "AB-100", "17")
        self.fails(1, "ship", "2024-04-01", "AB-100", "1")

    def test_back_dated_ship_that_breaks_later_movements_is_refused(self):
        # a ship dated before the delivery, and one dated before a later ship that would then overdraw
        self.fails(1, "ship", "2024-02-01", "AB-100", "1")
        self.write("movements.txt", "2024-03-01 AB-100 +5\n2024-03-10 AB-100 -5\n")
        err = self.fails(1, "ship", "2024-03-05", "AB-100", "1")
        self.assertIn("movements.txt: line 2", err)

    def test_same_day_ship_after_receive_in_file_order(self):
        self.write("movements.txt", "2024-03-01 AB-100 +5\n")
        self.ok("ship", "2024-03-01", "AB-100", "5")

    def test_bad_date_is_usage_error(self):
        for cmd in ("receive", "ship"):
            for date in ("2024-02-30", "2024-2-3", "tomorrow", "", "2024-13-01"):
                with self.subTest(cmd=cmd, date=date):
                    self.fails(2, cmd, date, "AB-100", "1")

    def test_wrong_arg_counts(self):
        for args in (("receive",), ("receive", "2024-01-01", "AB-100"), ("ship", "2024-01-01", "AB-100", "1", "a", "b")):
            self.fails(2, *args)

    def test_parse_error_in_movements_blocks_append(self):
        self.write("movements.txt", "2024-03-01 AB-100 +5\nnope\n")
        self.assertIn("movements.txt: line 2", self.fails(1, "receive", "2024-03-02", "AB-100", "1"))

    def test_unicode_note(self):
        out = self.ok("receive", "2024-04-01", "AB-100", "1", "café")
        self.assertEqual(out, "2024-04-01 AB-100 +1 café\n")
        self.assertIn("café", self.ok("history", "AB-100"))

